function addTwo(a: number, b: number): number {
  while (b !== 0) {
    const carry = (a & b) << 1;
    a = a ^ b;
    b = carry;
  }
  return a;
}

solutions.py:
class Solution:
    def addTwo(self, a: int, b: int) -> int:
        mask = 0xFFFFFFFF
        while b & mask:
            a, b = (a ^ b) & mask, ((a & b) << 1) & mask
        a &= mask
        # turn the 32-bit pattern back into a signed value
        return a if a < 0x80000000 else a - (1 << 32)

